head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.gViewerStat = "P"; // 처리시 뷰=P,  조회시 뷰=R,  사후심사 A
scwin.search_yn = false;
// 화면 리사이징

scwin.gAcptNo;
scwin.gIsurCd;
scwin.gSndlocTpCd;
scwin.gExmptYn; // 면제대상여부(bypass)

scwin.gDate;
scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.gLdMktTp = js_market;
scwin.gDutyYn = js_duty;
scwin.gDutyChrg = js_duty_chrg; // 세션정보
scwin.gJobTitle = js_jobtitl; // 팀장  : 09,  부서장: 40,  팀원: 03

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    await scwin.gform_onload();
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    panel_2.hide();
    panel_3.hide();
    const strDepCd = js_dep_cd.substring(0, 2);

    // 유가 공시팀(26**), 코스닥 공시팀(34**) => 보여준다.
    // if (js_dep_cd.substring(0,2) == '26'  || js_dep_cd.substring(0,2) == '34' ) {
    // if (js_dep_cd.substring(0,1) == '2'  || js_dep_cd.substring(0,2) == '34' ) {
    if (strDepCd === '24' || strDepCd === '25' || strDepCd === '2B') {
        // 24=채권상장, 25=상장심사부, 2B=증권상품
        panel_2.show("");
        panel_3.show("");
    } else if (strDepCd === '26' || strDepCd === '34') {
        // 공시팀인경우 당번만 보여준다 2013.03.26
        panel_3.show(""); // 담당자
        if (scwin.gDepCd === '2610' || scwin.gDepCd === '3410') {
            // 공시제도팀의 경우 팀장, 팀원 모두 공시제도팀공시만 볼 수 있다. 20210312 - IT운영팀
            panel_2.hide(); // 팀장

        } else {
            if (scwin.gJobTitle === '09' || scwin.gDutyYn === 'Y' || scwin.gDutyChrg === 'Y') {
                panel_2.show(""); // 팀장

            }
        }
    }

    // 처음엔 전체 체크
    chb_stat_all.setValue(0);
    chb_stat_00.setValue(1);
    chb_stat_02.setValue(1);
    chb_stat_01.setValue(1);
    chb_stat_10.setValue(0);
    chb_stat_20.setValue(0);
    chb_stat_30.setValue(0);
    chb_stat_35.setValue(0);
    chb_stat_40.setValue(0);
    chb_reg.setValue(0);

    // 처음엔 전체 체크
    chb_affstat_all.setValue(0);
    chb_affstat_00.setValue(1);
    chb_affstat_01.setValue(1);
    chb_affstat_10.setValue(0);
    chb_affstat_20.setValue(0);
    chb_affstat_30.setValue(0);
    chb_affstat_40.setValue(0);

    // 현재날짜 셋팅
    scwin.gDate = $c.ut.cGetToday("yyyymmdd");
    edt_SrchDay.setValue(scwin.gDate);

    // 팀 리스트 박스(소속부서와 같은 상위부서인 팀)
    // dts_dep.DataID = "/CodeAction.do?method=getDepUpCodeOrg"+
    const sbmOptions = {
        id : "sbm_dts_dep",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_dep=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // 담당자 리스트 박스(소속부서와 같은 상위부서인 팀원)
    const sbmOptions2 = {
        id : "sbm_dts_emp",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_emp=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name depListLoadComplete
 * @description dep List Load Complete 처리
 * @returns {void}
 * @hidden N
 */
scwin.depListLoadComplete = function() {
    cmb_TeamList.setValue(js_dep_cd);
    // 부서코드 가져온후에  초기검색
    scwin.initSearch();
};

/**
 * @method
 * @name initSearch
 * @description 화면 로딩시 디폴트 검색
 * @returns {void}
 * @hidden N
 */
scwin.initSearch = function() {
    scwin.reload('N');
};

/**
 * @method
 * @name reload
 * @description reload 처리
 * @param {*} pReload pReload
 * @returns {void}
 * @hidden N
 */
scwin.reload = function(pReload) {
    fn_CheckCond(pReload);
    setTimeout("fn_Reload('Y')", 30000); // 1초 = 1000 , 30초 = 30000

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************

};X < !담당자--;
검토대상;
클릭-- > async function(pReload) {
    // 일자 체크
    if (edt_SrchDay.getValue().length < 8) {
        await $c.win.alert("일자 올바르게 입력하십시오.");
        edt_SrchDay.focus();
        return;
    }
    let vStatCnt = 0;
    if (chb_stat_00.checked === true) {
        vStatCnt++;
    }
    if (chb_stat_02.checked === true) {
        vStatCnt++;
    }
    if (chb_stat_01.checked === true) {
        vStatCnt++;
    }
    if (chb_stat_10.checked === true) {
        vStatCnt++;
    }
    if (chb_stat_20.checked === true) {
        vStatCnt++;
    }
    if (chb_stat_30.checked === true) {
        vStatCnt++;
    }
    if (chb_stat_35.checked === true) {
        vStatCnt++;
    }
    if (chb_stat_40.checked === true) {
        vStatCnt++;
    }
    if (chb_reg.checked === true) {
        vStatCnt++;
    }
    let vAffStatCnt = 0;
    if (chb_affstat_00.checked === true) {
        vAffStatCnt++;
    }
    if (chb_affstat_01.checked === true) {
        vAffStatCnt++;
    }
    if (chb_affstat_10.checked === true) {
        vAffStatCnt++;
    }
    if (chb_affstat_20.checked === true) {
        vAffStatCnt++;
    }
    if (chb_affstat_30.checked === true) {
        vAffStatCnt++;
    }
    if (chb_affstat_40.checked === true) {
        vAffStatCnt++;
    }

    // 처리상태 1개 이상 체크
    if (vStatCnt < 1 && vAffStatCnt < 1) {
        await $c.win.alert("처리현황 또는 사후심사현황을 한개 이상  선택하십시요.");
        return;
    }
    scwin.gDate = edt_SrchDay.getValue();

    // 유가 공시팀(26**), 코스닥 공시팀(34**) =>  선택부서로
    // if (js_dep_cd.substring(0,2) == '26'  || js_dep_cd.substring(0,2) == '34' ) {
    if (js_dep_cd.substring(0, 1) === '2' || js_dep_cd.substring(0, 2) === '34') {
        scwin.gDepCd = cmb_TeamList.getValue();
        scwin.gEmpNo = cmb_EmpList.getValue();
    } else {
        scwin.gDepCd = ""; // 부서코드 없음 => 전체
        scwin.gEmpNo = "";
    }
    fn_Search(pReload);
};

/**
 * @method
 * @name getChkValue
 * @description get Chk Value 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.getChkValue = function(obj) {
    // return (obj.checked) ? "Y" : "N";
    if (obj.checked === true) {
        return obj.getValue();
    } else {
        return "0";
    }

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************

};X < !담당자--;
검토대상;
클릭-- > async function(pReload) {
    $c.cm.ShowWin_yn(grd_Grid, scwin.search_yn);

    /******************************************************************
    	2009.09.01 채권공시관련 - 채권상장팀이면 시장구분을 '4'로 셋팅
     ******************************************************************/
    if (js_bond_yn === "Y") {
        scwin.gLdMktTp = "4";
    }
    const url = "/DisclosureStudyAffact.do?method=listDisclosureStudyAffact&inputMessageId=DSCLSTUDYCOND_AFF_IN" + "&outputMessageId=DSCLSTUDYLIST_AFF_OUT" + "&ACPT_DATE=" + scwin.gDate + "&DEP_CD=" + scwin.gDepCd + "&EMP_NO=" + scwin.gEmpNo + "&LD_MKT_TP=" + scwin.gLdMktTp + "&STAT_00=" + scwin.getChkValue(chb_stat_00) + "&STAT_02=" + scwin.getChkValue(chb_stat_02) + "&STAT_01=" + scwin.getChkValue(chb_stat_01) + "&STAT_10=" + scwin.getChkValue(chb_stat_10) + "&STAT_20=" + scwin.getChkValue(chb_stat_20) + "&STAT_30=" + scwin.getChkValue(chb_stat_30) + "&STAT_35=" + scwin.getChkValue(chb_stat_35) + "&STAT_40=" + scwin.getChkValue(chb_stat_40) + "&STAT_REG=" + scwin.getChkValue(chb_reg) + "&AFF_STAT_00=" + scwin.getChkValue(chb_affstat_00) + "&AFF_STAT_01=" + scwin.getChkValue(chb_affstat_01) + "&AFF_STAT_10=" + scwin.getChkValue(chb_affstat_10) + "&AFF_STAT_20=" + scwin.getChkValue(chb_affstat_20) + "&AFF_STAT_30=" + scwin.getChkValue(chb_affstat_30) + "&AFF_STAT_40=" + scwin.getChkValue(chb_affstat_40) + "&UP_DEP_CD=" + js_belngdepcd;
    if (pReload !== 'Y') {
        // 자동refresh일때는 로그 없앰
    }

    // grd_Grid.Redraw ="false";
    const sbmOptions = {
        id : "sbm_dts_DsclStudyList",
        action : "&SCREN_ID=",
        ref : "",
        target : "dts_DsclStudyList=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    /*
    var fFrame = frame.Provider("/pageIndex").selPageID;
    var fname = frame.FrameID;
    if (fFrame == fname) {
    	ShowWin(grd_Grid);
    }
     */

};

/**
 * @method
 * @name setContnId
 * @description 그리드에서 클릭 row의 변수셋팅
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setContnId = function(obj) {
    scwin.gAcptNo = dts_DsclStudyList.getCellData(Number(obj), "ACPT_NO");
    scwin.gIsurCd = dts_DsclStudyList.getCellData(Number(obj), "ISUR_CD");
    scwin.gExmptYn = dts_DsclStudyList.getCellData(Number(obj), "EXMPT_OBJ_DISCLS_YN"); // bypass 여부

};

// 처리현황(전체)

/**
 * @method
 * @name checkAll
 * @description 전체가 체크일때
 * @returns {void}
 * @hidden N
 */
scwin.checkAll = function() {
    // 전체가 체크일때
    if (chb_stat_all.checked === true) {
        chb_stat_00.setValue(1);
        chb_stat_02.setValue(1);
        chb_stat_01.setValue(1);
        chb_stat_10.setValue(1);
        chb_stat_20.setValue(1);
        chb_stat_30.setValue(1);
        chb_stat_35.setValue(1);
        chb_stat_40.setValue(1);
        chb_reg.setValue(1);
    } else {
        chb_stat_00.setValue(0);
        chb_stat_02.setValue(0);
        chb_stat_01.setValue(0);
        chb_stat_10.setValue(0);
        chb_stat_20.setValue(0);
        chb_stat_30.setValue(0);
        chb_stat_35.setValue(0);
        chb_stat_40.setValue(0);
        chb_reg.setValue(0);
    }
};

// 처리현황(전체)

/**
 * @method
 * @name checkAll2
 * @description 전체가 체크일때
 * @returns {void}
 * @hidden N
 */
scwin.checkAll2 = function() {
    // 전체가 체크일때
    if (chb_affstat_all.checked === true) {
        chb_affstat_00.setValue(1);
        chb_affstat_01.setValue(1);
        chb_affstat_10.setValue(1);
        chb_affstat_20.setValue(1);
        chb_affstat_30.setValue(1);
        chb_affstat_40.setValue(1);
    } else {
        chb_affstat_00.setValue(0);
        chb_affstat_01.setValue(0);
        chb_affstat_10.setValue(0);
        chb_affstat_20.setValue(0);
        chb_affstat_30.setValue(0);
        chb_affstat_40.setValue(0);
    }
};

/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description 클릭된 값 변수에 셋팅
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = function(row, colid) {
    // 클릭된 값 변수에 셋팅
    scwin.setContnId(row);
    if (scwin.gExmptYn === 'Y') {
        // bypass 일경우 뷰어 상태는 'A'여야 함 'A'는 사후심사
        scwin.gViewerStat = 'A';
    } else {
        scwin.gViewerStat = 'P';
    }
    if (colid === "DOC_TITLE") {
        $c.stf.fn_OpenNoDisclViewer(scwin.gAcptNo, scwin.gViewerStat, js_emp_no, js_dep_cd, js_jobtitl, js_duty, js_duty_chrg, 'P', dts_DutyStatus); // 2013.05.14
        // fn_OpenNoDisclViewer(gAcptNo, gViewerStat);

    } else if (colid === "ACPT_DDTM") {
        $c.stf.openDisclAllList();
    } else if (colid === "COM_ABBRV") {
        $c.stf.fn_PopupCorpInfo();
    }
};

/**
 * @method
 * @name chb_stat_all_onclick
 * @description chb_stat_all 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.chb_stat_all_onclick = function() {
    scwin.checkAll();
};

/**
 * @method
 * @name chb_affstat_all_onclick
 * @description chb_affstat_all 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.chb_affstat_all_onclick = function() {
    scwin.checkAll2();
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Search_onclick = function() {
    fn_CheckCond('N');
    scwin.search_yn = true;
};

/**
 * @method
 * @name dts_dep_OnLoadError
 * @description dts_dep 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
