 */
scwin.dts_dep_OnLoadCompleted = function(rowcount) {
    scwin.depListLoadComplete();
};

/**
 * @method
 * @name dts_emp_OnLoadCompleted
 * @description dts_emp 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_emp_OnLoadCompleted = function(rowcount) {
    // setObjectValue(cmb_EmpList, js_emp_no) ;    // 로그인사람을 디폴트 선택시

};

/**
 * @method
 * @name cmb_TeamList_onselchange
 * @description cmb_TeamList onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_TeamList_onselchange = function() {
    scwin.gDepCd = $c.cp.valueOfIndex(cmb_TeamList, "VALUE", cmb_TeamList.getSelectedIndex());
    if (scwin.gDepCd === '') {
        cmb_EmpList.setValue('');
    }
    dts_emp.UseFilter = true;
    dts_emp.Filter();
    dts_emp.sort("DEP_CD", 0);
    // dts_emp.sort(); // W-Craft 주석처리

};

/**
 * @method
 * @name dts_emp_OnFilter
 * @description 부서코드에  해당하는 사원을 가져온다.
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_emp_OnFilter = function(row) {
    //  부서코드에  해당하는 사원을 가져온다.
    if (scwin.gDepCd === "") {
        // 전체일 경우 모두 보여준다.
        return true;
    } else {
        if (dts_emp.getCellData(row, "dep_cd") === scwin.gDepCd ||
            dts_emp.getCellData(row, "dep_cd") === "") {
            return true;
        } else {
            return false;
        }
    }
};

/**
 * @method
 * @name dts_DsclStudyList_OnLoadError
 * @description dts_DsclStudyList 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_DsclStudyList_OnLoadError = async function() {
    await $c.win.alert(dts_DsclStudyList);

    /*
    var fFrame = frame.Provider("../").ActiveFrame.FrameID;
    var fname = frame.FrameID;
    if (fFrame == fname) {
    	CloseWin('', grd_Grid);
    }
     */
    scwin.search_yn = false;
};

/**
 * @method
 * @name dts_DsclStudyList_OnLoadCompleted
 * @description dts_DsclStudyList 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_DsclStudyList_OnLoadCompleted = async function(rowcount) {
    if (dts_DsclStudyList.errorMsg) {
        await $c.win.alert(dts_DsclStudyList.errorMsg);
    } else {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
    }
    // grd_Grid.Redraw ="true";
    /*
    var fFrame = frame.Provider("../").ActiveFrame.FrameID;
    var fname = frame.FrameID;
    if (fFrame == fname) {
    	CloseWin(rowcount, grd_Grid);
    }*/

    scwin.search_yn = false;
};

/**
     * @method
     * @name btn_Excel_onclick
     * @description 「엑셀다운로드」 클릭 이벤트
     * @returns {void}
     * @hidden N
     */
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave('ULDSTF11000.xml', SCREN_PROCS_TP_CD_07);
    $c.data.downloadGridViewExcel(grd_Grid, {fileName: " 담당자검토대상 목록", type: "2"});
};

/**
 * @method
 * @name img_Cal_onclick
 * @description img_Cal 클릭 이벤트
 * @returns {void}
